INSERT INTO pre_visit_briefs (id, visit_id, patient_id, visit_reason, patient_type, history_summary, medication_summary, what_changed, missing_info, attention_signals, patient_questions, ai_considerations, queue_status, ai_label, confidence, source_ids, review_status, reviewed_by, reviewed_at, created_at) VALUES ('brief-001', 'visit-001', 'RM-102', 'Follow-up for Type 2 Diabetes and hyperlipidaemia management', 'returning', '32-year-old male. Known T2DM (since 2022) and hyperlipidaemia. Last visit: 18 Jun 2026. Previous HbA1c 7.8% (improved from 8.4%). LDL 3.4 mmol/L — still above target.', 'Metformin 500mg BD, Atorvastatin 20mg ON. Adherence reported as good.', 'HbA1c improved from 8.4% → 7.8%. LDL has not reached target. Weight stable. BP within normal range at last visit.', '["HbA1c result from today not yet available","Latest BP reading not recorded"]', '[{"type":"lab_due","title":"HbA1c overdue","detail":"HbA1c test was due 3 days ago. Result not in system.","severity":"medium"}]', '[]', '["Consider LDL target — may need statin dose increase or addition of ezetimibe","Renal function check recommended with long-term Metformin use"]', 'Position 1 · In consultation', 'AI_GENERATED', 'moderate', '[]', 'generated', NULL, NULL, '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO pre_visit_briefs (id, visit_id, patient_id, visit_reason, patient_type, history_summary, medication_summary, what_changed, missing_info, attention_signals, patient_questions, ai_considerations, queue_status, ai_label, confidence, source_ids, review_status, reviewed_by, reviewed_at, created_at) VALUES ('brief-002', 'visit-002', 'AK-118', 'Annual wellness review and thyroid panel results', 'returning', '38-year-old female. Hypothyroidism on Levothyroxine since 2020. Allergy: Penicillin (anaphylaxis), Sulfonamides. Last visit: 12 May 2026. TSH was 6.2 mIU/L (above normal), dose was increased.', 'Levothyroxine 50mcg OD (empty stomach). Recent dose increase 6 weeks ago.', 'Thyroid panel results now available. TSH at last check: 6.2 mIU/L. New result pending review. Patient reports improved energy levels.', '["New thyroid panel result — pending doctor review"]', '[{"type":"allergy","title":"Penicillin allergy on file","detail":"Severe anaphylaxis reaction documented. Ensure no penicillin-class antibiotic in any prescription.","severity":"high"},{"type":"allergy","title":"Sulfonamide allergy on file","detail":"Rash and fever reported. Avoid sulfonamide-containing medications.","severity":"medium"}]', '[]', '["Review TSH trend post dose adjustment — aim for TSH 0.5–2.5 mIU/L","Consider bone density monitoring with long-term levothyroxine"]', 'Position 2 · Waiting', 'AI_GENERATED', 'moderate', '[]', 'generated', NULL, NULL, '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO drug_interactions_db (id, drug_a, drug_b, severity, description, recommendation, created_at) VALUES ('di-001', 'warfarin', 'aspirin', 'severe', 'Increased risk of bleeding. Aspirin inhibits platelet aggregation and warfarin inhibits clotting factors.', 'Avoid combination. If essential, use lowest dose of aspirin with close INR monitoring.', '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO drug_interactions_db (id, drug_a, drug_b, severity, description, recommendation, created_at) VALUES ('di-002', 'metformin', 'alcohol', 'moderate', 'Increased risk of lactic acidosis with heavy alcohol use.', 'Advise patient to limit alcohol consumption.', '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO drug_interactions_db (id, drug_a, drug_b, severity, description, recommendation, created_at) VALUES ('di-003', 'atorvastatin', 'clarithromycin', 'severe', 'CYP3A4 inhibition increases atorvastatin levels significantly — risk of myopathy and rhabdomyolysis.', 'Temporarily withhold atorvastatin during clarithromycin course.', '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO drug_interactions_db (id, drug_a, drug_b, severity, description, recommendation, created_at) VALUES ('di-004', 'amlodipine', 'simvastatin', 'moderate', 'Amlodipine inhibits CYP3A4, increasing simvastatin levels and risk of myopathy.', 'Limit simvastatin dose to 20mg/day when combined with amlodipine.', '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
INSERT INTO drug_interactions_db (id, drug_a, drug_b, severity, description, recommendation, created_at) VALUES ('di-005', 'levothyroxine', 'calcium', 'moderate', 'Calcium reduces levothyroxine absorption.', 'Separate doses by at least 4 hours.', '2026-09-12 08:47:09') ON CONFLICT (id) DO NOTHING;
